content.text:
{
  "name": "INHECO 温控控制盒",
  "name_en": "INHECO TEC Control Box",
  "manufacturer": "INHECO",
  "description": "一款用于实验室温度控制模块的热电温控控制盒，可为加热/制冷附件提供控制与状态交互，常用于样品、板位或实验流程中的温度管理。",
  "description_en": "A thermoelectric temperature control box for laboratory temperature-control modules. It provides control and device interaction for heating/cooling accessories, and is commonly used for managing sample, plate, or workflow temperatures.",
  "actions": [
    {
      "action_name": "auto-setup",
      "description": "初始化并建立与温控控制盒的通信。",
      "description_en": "Initialize the device and establish communication with the temperature control box."
    },
    {
      "action_name": "auto-stop",
      "description": "停止温控控制盒的当前运行。",
      "description_en": "Stop the current operation of the temperature control box."
    },
    {
      "action_name": "auto-send_command",
      "description": "向温控控制盒发送底层命令并读取返回结果。",
      "description_en": "Send a low-level command to the temperature control box and read back the response."
    },
    {
      "action_name": "auto-set_touchscreen",
      "description": "启用或禁用控制盒触摸屏。",
      "description_en": "Enable or disable the control box touchscreen."
    },
    {
      "action_name": "auto-reset_action_display",
      "description": "重置控制盒的动作显示界面。",
      "description_en": "Reset the action display on the control box."
    }
  ],
  "tag_hints": [
    "thermoelectric temperature control",
    "lab automation temperature module",
    "heating and cooling control",
    "sample temperature management",
    "plate temperature control",
    "INHECO"
  ]
}

